from content import mc, num

TITLE = "Exam 3 — Synthesis and transfer"
QUESTIONS = [
    mc("camera", "A unit normal n_c is expressed in the camera frame. The camera uses Xc=R@Xw+t. Which expression converts the normal to the world frame?", "n_w = R.T @ n_c; translation does not act on a direction vector.", ["n_w = R.T @ (n_c-t)", "n_w = R @ n_c+t", "n_w = K @ n_c, followed by perspective division"], "Normals between rigid coordinate frames transform by rotation only. R maps world directions to camera directions; its transpose maps back. A general non-rigid affine transform would require a different normal rule, which is not asked here.", "HC1b pp.35–45; HC2a surface normals; prerequisite linear algebra"),
    mc("filtering", "You resize an image to one quarter of each spatial dimension by keeping every fourth pixel. Why should a suitable low-pass filter normally be applied BEFORE subsampling?", "High spatial frequencies can otherwise alias into false lower-frequency patterns.", ["It guarantees exact recovery of every original sample, even when the image has frequencies above the coarse-grid limit.", "Keeping every fourth pixel is itself an ideal low-pass filter, so preprocessing cannot influence aliasing.", "Low-pass filtering after subsampling removes aliasing just as reliably as filtering before subsampling."], "Subsampling reduces the representable frequency range. Filtering first suppresses frequencies that the coarse grid cannot represent; smoothing after aliasing does not undo it.", "HC2b pp.93–105; HC5b pp.38–39; Szeliski §3.4"),
    mc("reflectance", "A single image is modelled as I=A*S. Without further constraints, can it uniquely determine both albedo and shading?", "No; multiple albedo/shading combinations can produce the same image.", ["Yes, because one RGB pixel always supplies all geometry and material parameters.", "Yes, if the image has a high enough resolution, regardless of assumptions.", "No, but dividing every pixel by 255 always resolves the ambiguity."], "For positive scale c, A'=cA and S'=S/c preserve I, and further spatial ambiguities exist. Priors or extra observations are required.", "HC2a pp.4–6,21–23,47–48; Lab1"),
    mc("photometric", "Why can directly fitting the linear photometric-stereo model to strongly gamma-compressed pixel values be wrong?", "The model assumes a linear relation between measured intensity and radiance; the response must be linearized or modelled.", ["No correction is needed: any common gamma exponent preserves the linear equations exactly under a change of albedo alone.", "Gamma can always be absorbed into one constant camera gain, independent of intensity and light direction.", "Normalizing the fitted g removes all gamma effects, so only albedo can be affected by a nonlinear response."], "If recorded value is a nonlinear function of radiance, the original linear dot-product equations no longer describe the observations. Camera-response calibration or suitable raw data is needed.", "HC2a pp.19–20,61–62; Lab1"),
    mc("colour", "What determines a sensor channel's response to an illuminated coloured surface?", "The interaction of source spectrum, surface spectral reflectance and that channel's spectral sensitivity.", ["Only the surface's colour name, independent of light and sensor.", "Only the camera's extrinsic translation.", "Only the maximum channel value in a different pixel."], "A channel integrates wavelength-dependent contributions. Material colour alone does not fix measured RGB; illumination and sensor response matter.", "HC1b pp.67–71,80–86; Lab1"),
    mc("photometric", "An integrable normal-derived gradient field is reconstructed on a connected image domain with known x/y spacing and at least one nonzero slope. Which ambiguity remains without an anchor or boundary height?", "An additive constant in height.", ["An independent additive height constant for every pixel, even while all neighbouring derivatives stay fixed.", "An arbitrary multiplicative height scale, even though p and q and the x/y spacing are fixed.", "No height ambiguity remains, because unit-normal normalization already fixes the absolute reference height."], "Derivatives determine relative height, not the reference height. Fixing a height such as z(0,0)=0 removes this additive ambiguity on a connected region.", "HC2a pp.41–43; Lab1; Forsyth–Ponce §2.2"),
    mc("filtering", "Apply a normalized averaging kernel to a constant positive image with zero padding. What is correct?", "Interior outputs remain constant, but outputs near boundaries can be darker.", ["Every output must be identical, including boundaries, for any padding rule.", "All outputs become zero because averaging removes the DC component.", "Only corners become brighter because there are fewer neighbours."], "Interior samples see a full constant patch and weights sum to 1. At a zero-padded boundary some weighted values are 0. Padding is part of the filter's actual behaviour.", "HC2b pp.47–87; Lab2"),
    mc("morphology", "A closing operation uses a small structuring element. Which statement is safest?", "It can fill sufficiently small gaps/holes relative to the element's shape, but need not fill a large cavity.", ["One closing always fills every hole in every binary object.", "Closing means erosion followed by dilation.", "Closing removes every isolated foreground component without changing holes."], "Closing is scale- and shape-dependent. It is dilation followed by erosion, not general topological hole filling.", "HC2b pp.39–45; S2"),
    mc("morphology", "Erode an all-ones finite image using a centred 3 by 3 all-ones element with outside-image values defined as zero. What happens?", "Its outermost pixel border is removed.", ["It remains all ones because every stored pixel is one.", "Its foreground expands by one pixel outside the image.", "Every interior pixel becomes zero while the border stays one."], "For a border pixel, part of the tested support lies outside the image and encounters 0. Interior pixels whose entire support is inside survive.", "HC2b pp.27–38; S2"),
    mc("fourier", "Circularly translate a discrete image by an integer offset. How does the DFT transform under the standard shift theorem?", "Each coefficient is multiplied by a frequency-dependent phase factor of unit magnitude; its magnitude is unchanged.", ["Only magnitude changes; phase is fixed.", "Both magnitude and phase must stay unchanged because the image content is the same.", "The spectrum is only reordered by fftshift; individual frequency coefficients never change."], "The translated spectrum is the original spectrum times a unit-magnitude complex exponential. This is exact for a circular shift; cropping/zero-filled shifts can also change magnitude through boundaries. A particular coefficient can have an unchanged phase when its factor is 1.", "HC2b pp.97–104; Szeliski §3.4"),
    mc("fourier", "For a real-valued image, what relationship holds between opposite-frequency DFT coefficients?", "They are complex conjugates, with indices interpreted modulo the image size.", ["They are always identical in both real and imaginary components, so their phases must also be identical.", "Their imaginary components must all be zero, because the original image contains only real values.", "They are always negatives of each other, so the spectrum is antisymmetric at every opposite-frequency pair."], "Real-valued signals have Hermitian symmetry F[-k]=conj(F[k]). Thus magnitudes are symmetric and phases have opposite signs modulo a full turn, where defined.", "HC2b pp.99–104; Szeliski §3.4"),
    mc("features", "A detected intensity edge does not necessarily mark a depth discontinuity. Why?", "Reflectance or illumination changes can also cause an intensity edge.", ["Canny hysteresis guarantees that only physical depth boundaries survive its high threshold.", "Increasing Gaussian sigma makes intensity edges uniquely attributable to changes in depth.", "A material boundary cannot affect intensity, so every strong edge must be a depth discontinuity."], "Image derivatives measure appearance changes. Material boundaries, shadows, highlights and orientation changes can create edges without a depth break.", "HC3a; S3 introduction; HC2a"),
    mc("matching", "Why does SIFT search across a Gaussian scale space and use Difference-of-Gaussians extrema?", "To locate distinctive structures at their characteristic scales; DoG approximates a scale-normalized LoG response.", ["To guarantee invariance to arbitrary projective deformation of every patch.", "To recover absolute object size in metres from one image.", "To force all keypoints to have identical pixel scale."], "Scale selection allows corresponding structures to be detected after resizing. DoG is an efficient approximation, not a guarantee of unlimited viewpoint invariance.", "HC4a pp.36–42; S4; Szeliski §7.1"),
    mc("matching", "For positive affine brightness changes I'=aI+b with a>0, why can a normalized gradient-based SIFT descriptor be relatively robust?", "Gradients remove the constant offset b, and descriptor normalization reduces the common gain a.", ["The descriptor stores the original unnormalized RGB values exactly.", "SIFT estimates and removes every spatially varying shadow without assumptions.", "Dividing pixel coordinates by the focal length removes b."], "The derivative of aI+b is a times the derivative of I. Orientation and normalized magnitudes are relatively stable, provided clipping, quantization and nonlinear response do not disrupt the assumption.", "HC4a pp.41–44; Szeliski §7.1.2 pp.434–436"),
    mc("fitting", "An affine RANSAC sample contains three correct correspondences, but the three source points are collinear. Why should the sample be rejected?", "It is geometrically degenerate and does not uniquely constrain a general 2D affine transform.", ["Three pairs supply six scalar equations, so the transform is necessarily unique despite collinearity.", "Repeated least-squares refitting of the same three pairs automatically restores the missing rank.", "An all-inlier sample is always sufficient; degeneracy can occur only when at least one correspondence is wrong."], "All-inlier probability alone is not enough. A minimal sample must also have the geometry required to determine the model. For affine transforms, the [x,y,1] design rows must have rank 3.", "HC4a pp.17–22,45–55; Lab4"),
    mc("fitting", "Increasing the RANSAC inlier threshold gives a model many more counted inliers. Why is this not automatically evidence of a better geometric model?", "The larger threshold can admit poor matches and outliers as inliers.", ["A threshold has no influence on consensus size.", "A larger threshold always improves localization accuracy.", "Every counted inlier has exactly zero residual by definition."], "A threshold controls what residual is accepted. Compare fit quality using meaningful units and tolerances, rather than maximizing a count under arbitrarily relaxed criteria.", "HC4a pp.46–48; HC3a pp.99–109"),
    mc("flow", "A stationary scene undergoes a moving cast shadow. A brightness-constancy flow method reports motion in the shadow region. Which interpretation is correct?", "The appearance-constancy assumption for a physical surface point is violated; apparent image motion need not equal physical surface motion.", ["Every measured optical flow vector necessarily equals a 3D object's velocity.", "The reported vector must be a sign error, because a static scene guarantees zero estimated flow regardless of illumination.", "Increasing the window size always establishes that reported image motion corresponds to physical surface motion."], "Optical flow describes apparent image change and relies on assumptions. Lighting changes can mimic motion even with stationary geometry. A moving shadow pattern may itself have a consistent image displacement; that is not the underlying surface's displacement.", "HC3b pp.8–47,57–58; Lab3"),
    mc("flow", "Why can a coarse-to-fine flow method still fail on a tiny fast-moving object?", "The object can disappear or become indistinct at coarse levels, so its motion is not initialized correctly.", ["Pyramids make every flow observable regardless of texture or visibility.", "Small objects always have zero displacement at full resolution.", "The coarse-level flow already gives exact depth in metres."], "Pyramids reduce displacement but also reduce detail. Coarse estimation can miss thin or small structures, and later refinement may remain in the wrong solution basin.", "HC3b pp.52–58"),
    mc("tracking", "An online tracker updates its appearance model from its own predicted box. What is a major risk during occlusion?", "Incorrect predictions can contaminate the model and cause tracking drift.", ["The model can never change because the initial template is fixed by definition.", "Occlusion automatically provides perfect new positive labels.", "Any online update guarantees improved test accuracy."], "Self-labelled updates can learn the occluder or background. Controlled updates and re-detection can help, but no method is universally immune.", "HC3b pp.89–106; Lab3"),
    mc("geometry", "A camera translates while observing a scene with nearby and distant objects. One fitted panorama homography aligns the distant background but not the foreground. What is the main cause?", "Depth-dependent parallax; one global homography need not align the nonplanar scene.", ["The blend ramp is too narrow; widening it guarantees correction of every geometric mismatch.", "H has the wrong homogeneous scale; multiplying all its entries by a different nonzero scalar corrects foreground without moving background.", "The foreground and background require opposite matrix multiplication orders, even when the transform direction is fixed."], "Translation makes image displacement depend on depth. Blending can hide seams but cannot generally correct incompatible geometric alignments or double images.", "HC4a pp.33–35,60–64; S4; Lab4"),
    mc("geometry", "H maps source image coordinates to a reference image. A translation T then moves reference coordinates into a larger panorama canvas. With column vectors, which matrix maps source directly to the canvas?", "T @ H", ["H @ T", "H + T", "H.T @ T, regardless of the coordinate convention"], "Matrix composition applies the rightmost transformation first: source -> H -> reference -> T -> canvas. Transform direction and multiplication order must be explicit.", "HC4a pp.19,24–35; Lab4"),
    mc("classification", "Which classifier and prediction does this code implement for binary class labels? Squared distances preserve Euclidean neighbour order. Provided routine: `np.argsort(d2)` returns indices sorted by increasing d2.\n\n```python\nimport numpy as np\nX = np.array([[0,0], [0,1], [1,0], [3,3]], dtype=float)\ny = np.array([1,0,0,1])\nquery = np.array([.1,.1])\nd2 = ((X-query)**2).sum(axis=1)\nnearest = np.argsort(d2)[:3]\nprediction = int(y[nearest].sum() > 1)\n```", "Unweighted 3-nearest-neighbour majority voting predicts class 0, although the closest example has class 1.", ["1-nearest-neighbour classification predicts class 1; the two other selected labels never contribute.", "Unweighted 3-nearest-neighbour voting predicts class 1 because the closest example's label outweighs both others.", "K-means predicts class 0 after moving three learned centres; the array y is used only as an initialization seed."], "Squared distances are [.02,.82,.82,16.82]. The three nearest labels are [1,0,0], in an irrelevant tie order for the two zero labels. Their sum is 1, so the comparison is false and prediction=0. k-NN uses labelled examples; it does not update cluster centres. With k=1 the prediction would instead be 1.", "HC4b pp.37–53; Lab0"),
    mc("clustering", "For pixel clustering, why might features [R,G,B,alpha*x,alpha*y] give different segments from [R,G,B]?", "Spatial terms encourage location coherence, and alpha sets their relative importance against colour differences.", ["Adding x,y guarantees the true semantic labels without supervision.", "Feature scaling cannot affect Euclidean distances.", "K-means always returns connected regions even with colour-only features."], "K-means uses the metric in the supplied feature space. Scaling positions changes distances and can trade colour similarity against spatial compactness; it does not guarantee semantics or connectivity.", "HC5a pp.91–118"),
    mc("classification", "A training set contains label noise and is not linearly separable. Why use a soft-margin rather than a hard-margin linear SVM?", "It permits margin violations while balancing fit against regularization.", ["It removes every mislabeled point with certainty.", "It guarantees infinite margin for nonseparable data.", "It ignores the weight norm entirely and only memorizes pixels."], "A hard-margin separator is infeasible for nonseparable labels. Soft margin penalizes violations and controls model complexity; it does not know which labels are wrong.", "HC4b pp.69–78"),
    mc("metrics", "A CNN outputs softmax class scores that sum to one. Which conclusion is NOT guaranteed merely by applying softmax?", "The probabilities are well calibrated to actual correctness frequencies.", ["Each output is nonnegative.", "The outputs sum to one, up to numerical precision.", "Increasing one logit relative to the others increases its softmax probability."], "Softmax produces a normalized score distribution, but calibration is a separate empirical property. A high score alone is not proof that its stated frequency matches reality.", "HC5a p.5; HC5b p.78; prerequisite probability"),
    mc("optimization", "Consider this training sequence from the kind of loop taught in Lab5. What is the purpose of the first line? No executable PyTorch code is required.\n\n```python\noptimizer.zero_grad()\nloss.backward()\noptimizer.step()\n```", "Prevent unintended accumulation of earlier batches' gradients before this batch's update.", ["Reset learned model parameters to zero, ensuring that each batch starts from the same initialized network.", "Disable gradient recording for this batch while retaining earlier batches' stored gradients.", "Normalize every stored gradient to unit norm, so the learning rate becomes irrelevant to the next update."], "PyTorch gradient buffers accumulate unless cleared. Clearing gradients does not reset parameter values or disable gradient recording. Deliberate gradient accumulation is possible, but would need a different specified training schedule.", "Lab5 tutorial and training code"),
    mc("architectures", "A residual branch changes feature shape from H x W x C to H/2 x W/2 x 2C. What is required for an additive shortcut?", "A compatible shortcut, such as a stride-2 projection, so the tensors have matching shapes.", ["Add the mismatched tensors with no mapping; addition always changes the channel count automatically.", "Concatenate them and call the result an identity addition.", "Remove all nonlinearities from the entire network."], "Elementwise residual addition requires compatible dimensions. Identity shortcuts work only when the required shape matches; otherwise use an appropriate projection/downsampling path.", "HC6a pp.99–111"),
    mc("detection", "Multiply both a predicted box and its ground-truth box coordinates by the same positive scale. Which property is correct?", "IoU is unchanged, while an unnormalized squared coordinate-error loss generally scales by the square of that factor.", ["IoU doubles whenever object area doubles.", "Both losses must be identical for every pair of boxes.", "Coordinate error becomes scale invariant just by summing its four components."], "Intersection and union areas both scale by the square factor, so their ratio stays fixed. Squared coordinate errors also scale by the square factor, without cancellation.", "S5 Exercise 4; YOLOv4 §2.2"),
    mc("stereo", "For an ideal rectified stereo pair with parallel optical axes and a horizontal baseline, why are epipolar lines parallel?", "The epipoles are at infinity in the horizontal baseline direction.", ["Every scene point has the same depth.", "Both cameras have exactly the same optical centre.", "The fundamental matrix maps every point to the image's principal point."], "The other camera centre projects to a point at infinity when the baseline is parallel to the image plane. Corresponding points lie on horizontal scanlines after rectification.", "HC6b pp.50–90"),
    mc("stereo", "Which description of a standard multi-view reconstruction pipeline is correct?", "SfM estimates camera poses and sparse structure; bundle adjustment refines poses and points jointly; MVS can densify using estimated cameras.", ["MVS always estimates metric scale from arbitrary uncalibrated image content alone.", "Bundle adjustment modifies only colour histograms and never camera parameters.", "SfM requires only one camera image with no priors or known geometry."], "SfM recovers geometry from correspondences and motion. Ordinary monocular reconstruction retains a global scale ambiguity without a metric reference. MVS and bundle adjustment have different roles.", "HC6b pp.108–149"),
    num("camera", "An original camera has fx=800, fy=600, cx=320, cy=240 and zero skew. Crop away 40 pixels from the left and 20 from the top; then halve both spatial dimensions. Use continuous coordinates with no half-pixel offsets. A camera-frame point is [0.5,1,2]. Report its final image v coordinate, using the virtual image plane in front of the camera.", 260.0, "After crop and resize: fy'=300 and cy'=(240-20)/2=110. v'=300*(1/2)+110=260. Extrinsics do not change.", "HC1b pp.24–45; S1"),
    num("colour", "For the RGB image below, compute normalized RGB PER PIXEL, then report the spatial mean of its normalized red channel. For black pixels, define all normalized channels as zero.\n\n```python\nimport numpy as np\nI = np.array([[[6,1,3], [2,6,2]],\n              [[0,0,0], [1,1,2]]], dtype=float)\ns = I.sum(axis=2, keepdims=True)\nsafe = np.where(s == 0, 1, s)\nnormalized = I / safe\nanswer = normalized[:, :, 0].mean()\n```\n\nProvided function: `np.where(condition, a, b)` selects a where the condition is true and b elsewhere. Black pixels are included in the spatial mean.", 0.2625, "The per-pixel sums are [[10,10],[0,4]], with the zero denominator replaced by 1. Normalized red values are [[.6,.2],[0,.25]]. Their mean is 1.05/4=.2625; submit .26. Normalizing a spatially averaged RGB vector would be a different calculation.", "Lab1 Section 1; Lab0 array axes"),
    num("photometric", "Let estimated height gradients be p(x,y)=dz/dx=y and q(x,y)=dz/dy=2x. Start with z(0,0)=0. Integrate continuously to (2,3) along path A: x first then y; and path B: y first then x. Report the absolute difference between the two resulting heights.", 6.0, "Path A: p=0 along y=0, then q=4 along x=2, giving z_A=12. Path B: q=0 along x=0, then p=3 along y=3, giving z_B=6. Difference=6. The field is not integrable because dp/dy=1 differs from dq/dx=2.", "HC2a pp.41–43; Lab1"),
    num("reflectance", "Use calibrated Lambertian intensity I=rho*max(n dot l,0), with unit vectors n=[2/3,-1/3,2/3] and l=[0,0.6,0.8], rho=0.75, and unit light strength/gain. Report I.", 0.25, "n dot l = (-1/3)*.6+(2/3)*.8=1/3. It is positive, so I=.75/3=.25.", "HC2a pp.12–20; S1; Lab1"),
    num("morphology", "A 9 by 9 binary image is zero except for a 3 by 3 all-ones block at rows 3..5 and columns 3..5 (inclusive, zero-based), and a single foreground pixel at (0,0). Apply opening with a centred 3 by 3 all-ones element, zero outside the image, retaining the same shape after each stage. Report the final foreground-pixel count.", 9, "Erosion leaves only the central pixel (4,4); the isolated corner pixel disappears. Dilation restores the central 3 by 3 block, giving 9 pixels. It does not restore the isolated noise.", "HC2b pp.39–42; S2", True),
    num("filtering", "Use the median of three entries: `med(v)=sorted(v)[1]`. Let a=[0,0,10] and b=[0,10,0], with elementwise addition. Report med(a+b)-med(a)-med(b) as an exact integer.", 10, "a+b=[0,10,10], whose median is 10. Both original medians are 0. The difference is 10, a concrete failure of additivity proving that median filtering is nonlinear.", "HC2b pp.47,89–91; Lab2", True),
    num("fourier", "For f=[1,0,2,0] and h=[0,1,0,1], use 4-point CIRCULAR convolution c[k]=sum(n=0..3) f[n]*h[(k-n) modulo 4]. Report c[3] as an exact integer. This is the result of multiplying their unpadded 4-point DFTs and applying the inverse DFT.", 3, "c[3]=1*h[3]+0*h[2]+2*h[1]+0*h[0]=1+2=3. Wrap-around is part of the defined operation.", "HC2b pp.101–103; Szeliski §3.4", True),
    num("features", "The grid below contains gradient magnitudes AFTER non-maximum suppression. Use 8-neighbour Canny hysteresis: strong means >=9; weak means >=4 and <9; lower values are rejected. Retain every weak pixel connected through weak/strong pixels to a strong pixel. Report the retained pixel count.\n\n```text\n10 6 0 0 5 5 0\n 0 6 0 0 0 5 0\n 0 6 6 0 0 0 0\n```", 5, "The left group has one strong 10 and four connected weak 6s, so all 5 survive. The three 5s on the right have no connection to a strong seed and are discarded.", "HC3a pp.58–65; S2", True),
    num("features", "Use equal weights for a four-pixel window with Ix=[1,0,1,2] and Iy=[0,2,1,0]. Construct M=[[sum(Ix^2),sum(Ix*Iy)],[sum(Ix*Iy),sum(Iy^2)]]. Report the Shi–Tomasi score, the smaller eigenvalue. Provided formula for symmetric [[a,b],[b,d]]: lambda_min=(a+d-sqrt((a-d)^2+4*b*b))/2.", 4.381966011250105, "M=[[6,1],[1,5]]. lambda_min=(11-sqrt(5))/2=4.381966. Submit 4.38. The score tests the least constrained direction.", "S3; Lab3 Sections 2–3"),
    num("flow", "A flow at one-eighth spatial resolution is [u,v]=[1.75,-0.5] in COARSE pixels. Upsample to full resolution with the correct vector-unit scaling, then add a full-resolution residual flow [0.25,0.75]. Report the Euclidean magnitude of the resulting full-resolution vector.", 14.615915982243466, "Scale coarse displacement by 8: [14,-4]. Add the residual: [14.25,-3.25]. Magnitude=sqrt(14.25^2+3.25^2)=about 14.62 pixels. Resizing the array alone is not enough.", "HC3b pp.48–54; Lab3"),
    num("fitting", "An affine RANSAC uses minimal samples of 3 point pairs and independently sampled inlier fraction w=0.4. Assume all-inlier samples are nondegenerate. Use N=ceil(log(1-p)/log(1-w^3)). Report the minimum integer N for p=0.999.", 105, "w^3=.064. log(.001)/log(.936)=104.4417. Ceiling gives 105. A homography would require a different sample size and a larger budget.", "HC3a pp.104–105; Lab4", True),
    num("geometry", "A nonsingular homography maps these four source points to targets:\n\n```text\n(0,0) -> (1,2)\n(1,0) -> (3,2)\n(0,1) -> (1,4)\n(1,1) -> (3,3)\n```\n\nUse H=[[a,b,c],[d,e,f],[g,h,1]], so x'=(a*x+b*y+c)/(g*x+h*y+1), y'=(d*x+e*y+f)/(g*x+h*y+1). Rearrange the eight scalar equations into a linear system. You may use the provided least-squares routine `np.linalg.lstsq(A, rhs, rcond=None)[0]` to solve a full-rank system. Report the target x coordinate for source (0.5,0.5).", 2.3333333333333335, "The first pair gives c=1,f=2. The next pairs imply a=3g+2,d=2g,b=h,e=4h+2. The last pair gives h=0,g=1. Thus H=[[5,0,1],[2,2,2],[1,0,1]]. At (.5,.5), x'=3.5/1.5=7/3; submit 2.33. Averaging target corner positions would not implement a projective map.", "HC4a pp.47–55; S4"),
    num("matching", "A matcher returns SQUARED Euclidean distances [D1,D2], nearest first. Apply Lowe's test to the ordinary distances: sqrt(D1)/sqrt(D2)<0.7. For the rows below, report the largest ordinary nearest distance among accepted matches.\n\n```text\n[[4,9], [9,16], [1,4], [25,36], [.25,1]]\n```", 2.0, "Ordinary ratios are [2/3,3/4,1/2,5/6,1/2]. Accepted nearest distances are [2,1,.5], whose maximum is 2. Comparing D1/D2 directly with .7 would use the wrong threshold.", "HC4a pp.43–44; S4; Lab4"),
    num("classification", "A 1D visual vocabulary has centres [0,4,8]. Quantize descriptors [1,3,5,7,8,9] to their nearest centre using Euclidean distance. Build counts, then L1-normalize by the number of descriptors. Report the normalized bin value for centre 8.", 0.5, "Assignments produce counts [1,2,3]. After normalization by 6, the final bin is 3/6=.5. The fixed vocabulary gives the same histogram length for every image.", "HC4b pp.23–28; S4"),
    num("metrics", "A binary classifier predicts positive iff score>=0.6. True labels are [1,0,1,0,1,0] and scores are [.9,.8,.7,.6,.5,.4], in the same order. Report F1 for the positive class as a fraction.", 0.5714285714285714, "The first four predictions are positive. TP=2, FP=2, FN=1. F1=4/(4+2+1)=4/7=.5714286; submit .57. The score exactly at .6 is positive because the rule is inclusive.", "HC4b pp.80–86; S4"),
    num("metrics", "One class has 4 ground-truth objects. After score-ordered, one-to-one matching, ranked detections are [FP,TP,FP,TP,TP]. Use ALL-POINTS INTERPOLATED AP: sum each positive recall increment times the maximum precision at that recall or any later recall. Precision beyond maximum achieved recall is zero. Report AP as a fraction. This is NOT 11-point AP or raw uninterpolated AP.", 0.45, "Cumulative precisions are [0,1/2,1/3,2/4,3/5], recalls [0,1/4,1/4,2/4,3/4]. The future-maximum precision at each TP is .6. Three increments of .25 contribute .25*.6 each, so AP=.45. The missing final quarter of recall contributes zero; raw uninterpolated AP would instead be .40.", "HC5a pp.68–78; S4"),
    num("architectures", "A residual block has an identity shortcut and this dense bottleneck branch: 1 x 1 convolution 64->16 channels; 3 x 3 convolution 16->16; 1 x 1 convolution 16->64. Include one bias per output channel in EACH convolution. There is no normalization layer or trainable shortcut. Report total trainable parameters.", 4448, "Counts are (64+1)*16=1040, (3*3*16+1)*16=2320, and (16+1)*64=1088. Total=4448. The identity shortcut has no parameters.", "HC5b pp.70–73; HC6a pp.107–111; S5", True),
    num("cnn", "A standard 3D convolution processes a video tensor with 2 input channels and uses 5 output channels. Each filter has temporal x height x width size 3 x 3 x 3. Include one bias per output channel. No groups. Report the trainable parameter count; the video length and spatial image size do not enter this count.", 275, "Each filter has 3*3*3*2=54 weights. Five filters and five biases give (54+1)*5=275. Do not count frames as independent input channels for this 3D convolution.", "S5 Exercise 5", True),
    num("detection", "Use the ORIGINAL YOLO v1 confidence convention: box_confidence=Pr(object)*IoU(predicted_box,GT); class_specific_score=Pr(class|object)*box_confidence. Given Pr(object)=0.75, IoU=0.6 and Pr(class|object)=0.8, report the class-specific score.", 0.36, "Box confidence=.75*.6=.45. Class-specific score=.8*.45=.36. The convention is explicitly given because different YOLO versions use different outputs and targets.", "HC6a pp.66–72; SOURCE_NOTES"),
    num("stereo", "For rectified stereo, Z=f*B/d. Let f=900 pixels, B=0.2 metres, d=12 pixels, and small disparity-error magnitude delta_d=0.25 pixel. Use FIRST-ORDER error propagation |delta_Z| approximately (f*B/d^2)*|delta_d|. Report the estimated depth-error magnitude in metres, not the exact finite-difference error.", 0.3125, "Sensitivity magnitude is 180/144=1.25 metres per pixel. Multiply by .25: .3125 metres, so submit .31. Depth becomes increasingly sensitive to disparity errors at small disparity/large depth.", "HC6b pp.84–90; Szeliski §12.1; prerequisite calculus"),
]
